package("nexus-blake3")
    set_homepage("https://github.com/BLAKE3-team/BLAKE3")
    set_description("Pinned official BLAKE3 C implementation")
    set_license("Apache-2.0")
    add_urls(os.getenv("NEXUS_BLAKE3_SOURCE") or "https://github.com/BLAKE3-team/BLAKE3.git")
    add_versions("1.8.4", "b97a24f8754819755ef78d8016c0391c65c943c5")
    add_links("blake3")
    on_install("linux", function (package)
        import("package.tools.cmake")
        local root = os.curdir()
        os.cd("c")
        cmake.install(package, {"-DBUILD_SHARED_LIBS=OFF", "-DBUILD_TESTING=OFF", "-DBLAKE3_SIMD_TYPE=none", "-DBLAKE3_USE_TBB=OFF"})
        os.cd(root)
        os.cp("LICENSE_A2", package:installdir("share/licenses/nexus-blake3"))
    end)
    on_test(function (package)
        assert(package:has_cincludes("blake3.h"))
    end)
package_end()
